{
  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "Le point 3.6, page 1, prévoit expressément l’autorisation de démarches préliminaires pour acheter les lots liés à l’église, ce qui constitue un objet foncier explicite."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "Le point 5.2, page 1, prévoit l’autorisation de l’état relatif à la vente des immeubles pour défaut de paiement de taxes municipales, sans constater une vente réalisée."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "Le point 8.1, page 2, prévoit une résolution d’appui à la CPTAQ pour une fin autre que l’agriculture : l’adoption prévue concerne cet appui municipal, non une autorisation acquise de la CPTAQ."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "Le point 10.1, page 2, annonce explicitement l’avis de motion du règlement 169-2019-01 remplaçant le règlement sur les nuisances, à titre d’étape prévue."
    },
    {
      "item": "i05",
      "choice": "absent",
      "reason": "Cette proposition reprend exactement le même objet et la même étape du point 5.2 que l’item i02, alors qu’un doublon du même type et du même fait ne constitue pas une unité distincte."
    }
  ]
}
